+/**
+ * @param {?string} displayName - The name.
+ * @returns {string} what to display as avatar for the name.
+ */
+function avatarPlaceholder(displayName) {
+  return (
+    Array.from(
+      displayName?.normalize().replaceAll(/[^\p{Letter}\p{Nd}]+/gu, "")
+    )[0]?.toUpperCase() || ""
+  );
+}
+
